   <DDP_COMPONENT_OVLSYS_DLO_ASYNC10>; 
 // 表示android 端crtc3 只有1 个plane，使用OVL7_L0(最下层)。 
 crtc3-layer-nr = <1>; 
 crtc3-layer-table = <0x4000>; 

; 

