  compatible = "ilitek,touch"; 
  reg = <0x41>; 
  interrupt-parent = <&pio>; 
  interrupts = <9 0x0>; 
  ilitek,irq-gpio = <&pio 9 0x0>; 
  ilitek,reset-gpio = <&pio 60 0x0>; 
  ilitek,vbus = "vcc_i2c"; 
  ilitek,name = "ilitek_i2c"; 
 }; 
}; 

