/* C code Sample */ 
#include <linux/gpio.h> 
#include <linux/consumer.h> 
struct gpio_desc *gpio_spec; 

gpio_spec = devm_gpiod_get(&pdev->dev, "test", GPIOD_OUT_HIGH); 

