gpiod_get_value(gpio_spec); 

/* Set direction to output mode and output value*/ 
gpiod_direction_output(gpio_spec, 1 or 0); 

gpiod_set_value(gpio_spec, 1 or 0); 

/* Free this GPIO if needed*/ 
devm_gpiod_put(&pdev->dev, gpio_spec); 
